<body>
<div class="wrap">
  <header>
    <div>
      <h1>Follow-Up CRM</h1>
      <div class="sub">Tiny pipeline tracker for freelancers and solo operators. Everything stays in this browser.</div>
    </div>
    <div class="actions">
      <button class="secondary" onclick="exportCSV()">Export CSV</button>
      <button class="danger" onclick="clearAll()">Clear All</button>
    </div>
  </header>

  <section class="panel">
    <form id="crmForm" class="form">
      <input type="hidden" id="id">
      <div><label>Name</label><input id="name" required placeholder="Jane Client"></div>
      <div><label>Company</label><input id="company" placeholder="Acme Co."></div>
      <div><label>Email</label><input id="email" type="email" placeholder="jane@email.com"></div>
      <div><label>Value</label><input id="value" type="number" min="0" placeholder="2500"></div>
      <div><label>Status</label><select id="status"><option>Lead</option><option>Contacted</option><option>Proposal Sent</option><option>Won</option><option>Lost</option></select></div>
      <div><label>Next Follow-Up</label><input id="followDate" type="date" required></div>
      <div class="span2"><label>Opportunity</label><input id="opportunity" placeholder="Website redesign, monthly retainer, consulting call..."></div>
      <div class="span4"><label>Notes</label><textarea id="notes" placeholder="Last conversation, objections, next action..."></textarea></div>
      <div class="span4 actions">
        <button type="submit" id="saveBtn">Save Contact</button>
        <button type="button" class="secondary" onclick="resetForm()">Cancel Edit</button>
      </div>
    </form>

    <div class="toolbar">
      <input id="search" placeholder="Search name, company, opportunity, notes..." oninput="render()">
      <select id="statusFilter" onchange="render()">
        <option value="">All statuses</option><option>Lead</option><option>Contacted</option><option>Proposal Sent</option><option>Won</option><option>Lost</option>
      </select>
      <select id="sortBy" onchange="render()">
        <option value="date">Sort by follow-up date</option>
        <option value="value">Sort by value</option>
        <option value="name">Sort by name</option>
      </select>
      <button class="secondary" onclick="seedDemo()">Add Demo Data</button>
    </div>

    <div class="stats" id="stats"></div>
    <div class="buckets">
      <div class="bucket"><h2>Overdue</h2><div id="overdue"></div></div>
      <div class="bucket"><h2>Today</h2><div id="today"></div></div>
      <div class="bucket"><h2>Upcoming</h2><div id="upcoming"></div></div>
    </div>
  </section>
</div>

<script>
const KEY = "solo_followup_crm_v1";
let contacts = JSON.parse(localStorage.getItem(KEY) || "[]");

const $ = id => document.getElementById(id);
const todayISO = () => new Date().toISOString().slice(0,10);
$("followDate").value = todayISO();

function save(){
  localStorage.setItem(KEY, JSON.stringify(contacts));
  render();
}

$("crmForm").addEventListener("submit", e => {
  e.preventDefault();
  const item = {
    id: $("id").value || crypto.randomUUID(),
    name: $("name").value.trim(),
    company: $("company").value.trim(),
    email: $("email").value.trim(),
    value: Number($("value").value || 0),
    status: $("status").value,
    followDate: $("followDate").value,
    opportunity: $("opportunity").value.trim(),
    notes: $("notes").value.trim(),
    updated: new Date().toISOString()
  };
  const i = contacts.findIndex(c => c.id === item.id);
  if(i >= 0) contacts[i] = item; else contacts.push(item);
  resetForm();
  save();
});

function resetForm(){
  $("crmForm").reset();
  $("id").value = "";
  $("followDate").value = todayISO();
  $("saveBtn").textContent = "Save Contact";
}

function editContact(id){
  const c = contacts.find(x => x.id === id);
  Object.keys(c).forEach(k => $(k) && ($(k).value = c[k]));
  $("saveBtn").textContent = "Update Contact";
  scrollTo({top:0, behavior:"smooth"});
}

function deleteContact(id){
  if(confirm("Delete this contact?")){
    contacts = contacts.filter(c => c.id !== id);
    save();
  }
}

function bucketOf(date){
  const t = todayISO();
  if(date < t) return "overdue";
  if(date === t) return "today";
  return "upcoming";
}

function filtered(){
  const q = $("search").value.toLowerCase();
  const sf = $("statusFilter").value;
  let list = contacts.filter(c =>
    (!sf || c.status === sf) &&
    [c.name,c.company,c.email,c.opportunity,c.notes].join(" ").toLowerCase().includes(q)
  );
  const sort = $("sortBy").value;
  list.sort((a,b) => sort === "value" ? b.value - a.value : sort === "name" ? a.name.localeCompare(b.name) : a.followDate.localeCompare(b.followDate));
  return list;
}

function render(){
  const list = filtered();
  const buckets = {overdue:[], today:[], upcoming:[]};
  list.forEach(c => buckets[bucketOf(c.followDate)].push(c));

  $("stats").innerHTML = `
    <div class="stat"><b>${contacts.length}</b><div>Total contacts</div></div>
    <div class="stat"><b>${buckets.overdue.length}</b><div>Overdue</div></div>
    <div class="stat"><b>${buckets.today.length}</b><div>Due today</div></div>
    <div class="stat"><b>$${contacts.reduce((s,c)=>s+c.value,0).toLocaleString()}</b><div>Pipeline value</div></div>
  `;

  ["overdue","today","upcoming"].forEach(type => {
    $(type).innerHTML = buckets[type].length ? buckets[type].map(card).join("") : `<div class="empty">No ${type} follow-ups.</div>`;
  });
}

function card(c){
  const cls = bucketOf(c.followDate);
  return `
    <div class="card">
      <div class="top">
        <div>
          <div class="name">${esc(c.name)}</div>
          <div class="meta">${esc(c.company || "No company")} · ${esc(c.status)} · $${Number(c.value).toLocaleString()}</div>
        </div>
        <span class="pill ${cls}">${c.followDate}</span>
      </div>
      <div class="meta">${esc(c.opportunity || "No opportunity listed")}</div>
      <div class="note">${esc(c.notes || "No notes yet.")}</div>
      <div class="meta">${c.email ? `<a style="color:var(--accent)" href="mailto:${esc(c.email)}">${esc(c.email)}</a>` : "No email"}</div>
      <div class="cardBtns">
        <button class="secondary" onclick="editContact('${c.id}')">Edit</button>
        <button class="danger" onclick="deleteContact('${c.id}')">Delete</button>
      </div>
    </div>
  `;
}

function esc(s){
  return String(s).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
}

function exportCSV(){
  const headers = ["Name","Company","Email","Value","Status","Next Follow-Up","Opportunity","Notes","Updated"];
  const rows = contacts.map(c => [c.name,c.company,c.email,c.value,c.status,c.followDate,c.opportunity,c.notes,c.updated]);
  const csv = [headers, ...rows].map(r => r.map(v => `"${String(v ?? "").replaceAll('"','""')}"`).join(",")).join("\n");
  const blob = new Blob([csv], {type:"text/csv"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "follow-up-crm.csv";
  a.click();
  URL.revokeObjectURL(a.href);
}

function clearAll(){
  if(confirm("Clear every saved contact from this browser?")){
    contacts = [];
    save();
  }
}

function seedDemo(){
  const d = new Date();
  const iso = offset => new Date(d.getFullYear(), d.getMonth(), d.getDate()+offset).toISOString().slice(0,10);
  contacts.push(
    {id:crypto.randomUUID(),name:"Maya Patel",company:"Northline Studio",email:"maya@example.com",value:3200,status:"Proposal Sent",followDate:iso(-2),opportunity:"Brand refresh package",notes:"Asked for revised timeline and payment split.",updated:new Date().toISOString()},
    {id:crypto.randomUUID(),name:"Chris Morgan",company:"Morgan HVAC",email:"chris@example.com",value:900,status:"Contacted",followDate:iso(0),opportunity:"Landing page tune-up",notes:"Call went well. Send examples before noon.",updated:new Date().toISOString()},
    {id:crypto.randomUUID(),name:"Lena Brooks",company:"Brooks Legal",email:"lena@example.com",value:1800,status:"Lead",followDate:iso(5),opportunity:"Monthly content retainer",notes:"Warm intro. Follow up with simple scope.",updated:new Date().toISOString()}
  );
  save();
}

render();
</script>
</body>
</html>

