  );
  const sort = $("sortBy").value;
  list.sort((a,b) => {
    if (sort === "value") return b.value - a.value;
    if (sort === "name") return a.name.localeCompare(b.name);
    if (sort === "lastContacted") return (b.lastContacted || "").localeCompare(a.lastContacted || "");
    return a.followDate.localeCompare(b.followDate);
  });
  return list;
}

function render(){
  const list = filtered();
  const buckets = {overdue:[], today:[], upcoming:[]};
  list.forEach(c => buckets[bucketOf(c.followDate)].push(c));

  const contactedCount = contacts.filter(c => c.lastContacted).length;

  $("stats").innerHTML = `
    <div class="stat"><b>${contacts.length}</b><div>Total contacts</div></div>
    <div class="stat"><b>${buckets.overdue.length}</b><div>Overdue</div></div>
    <div class="stat"><b>${buckets.today.length}</b><div>Due today</div></div>
    <div class="stat"><b>${contactedCount}</b><div>Contacted before</div></div>
  `;

  ["overdue","today","upcoming"].forEach(type => {
    $(type).innerHTML = buckets[type].length ? buckets[type].map(card).join("") : `<div class="empty">No ${type} follow-ups.</div>`;
  });
}

function card(c){
  const cls = bucketOf(c.followDate);
  return `
    <div class="card">
      <div class="top">
        <div>
          <div class="name">${esc(c.name)}</div>
          <div class="meta">${esc(c.company || "No company")} · ${esc(c.status)} · $${Number(c.value).toLocaleString()}</div>
        </div>
        <span class="pill ${cls}">${c.followDate}</span>
      </div>

      <div class="meta">${esc(c.opportunity || "No opportunity listed")}</div>
      <div class="note">${esc(c.notes || "No notes yet.")}</div>
      <div class="last">Last contacted ${esc(humanDateTime(c.lastContacted))}</div>
      <div class="meta">${c.email ? `<a style="color:var(--accent)" href="mailto:${esc(c.email)}">${esc(c.email)}</a>` : "No email"}</div>

      <div class="quickBtns">
        <button class="quick done" onclick="markFollowedUp('${c.id}')">Followed up today</button>
        <button class="quick snooze" onclick="reschedule('${c.id}', 1)">+1 day</button>
        <button class="quick snooze" onclick="reschedule('${c.id}', 7)">+7 days</button>
        <button class="quick done" onclick="markAndReschedule('${c.id}', 7)">Done, +7</button>
      </div>

      <div class="cardBtns">
        <button class="secondary" onclick="editContact('${c.id}')">Edit</button>
        <button class="danger" onclick="deleteContact('${c.id}')">Delete</button>
      </div>
    </div>
  `;
}

function esc(s){
  return String(s).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
}

function exportCSV(){
  const headers = ["Name","Company","Email","Value","Status","Next Follow-Up","Last Contacted","Opportunity","Notes","Updated"];
  const rows = contacts.map(c => [
    c.name,
    c.company,
    c.email,
    c.value,
    c.status,
    c.followDate,
    c.lastContacted ? humanDateTime(c.lastContacted) : "",
    c.opportunity,
    c.notes,
    c.updated
  ]);
  const csv = [headers, ...rows].map(r => r.map(v => `"${String(v ?? "").replaceAll('"','""')}"`).join(",")).join("\n");
  const blob = new Blob([csv], {type:"text/csv"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "follow-up-crm.csv";
  a.click();
  URL.revokeObjectURL(a.href);
}

function clearAll(){
  if(confirm("Clear every saved contact from this browser?")){
    contacts = [];
    save();
  }
}

